export const DISPLAY_NAME = "agentic kit" // the kit's name in prose
export const CLI = "ak" // the command a person types
export const MARKETPLACE = "ak" // the plugin marketplace: ids are <plugin>@<marketplace>
export const ENV_PREFIX = "AK_" // prefix of every environment variable: env('PATH') reads <prefix>PATH
export const HOME_DIR = ".ak" // the dot-folder: ~/<home_dir> is the global home, <repo>/<home_dir> a scope
export const REPO_DIR = "agentic-kit" // the default checkout folder under $HOME: ~/<repo_dir>
